/* ================= ENTREGAS PREVISTAS (Mapa de Entrega -> controle por filial) =================
   Importa o PDF do Mapa de Entrega (TransFlow), lê cada pacote com todos os dados do layout
   (pacote/REL, tipo de venda, volumes, NF, cliente completo, endereço, peso/m³, prazo) e separa
   por filial atendente. A filial vem da tabela "Cidade -> Filial" (editável) e pode ser
   corrigida pacote a pacote. Exporta Excel (1 aba por filial) ou PDF (1 página por filial). */
(function(){
  const K_PREV = "tambasa_previstas", K_CID = "tambasa_cidade_filial";
  // Cidades que já sabemos qual filial atende (o usuário pode alterar tudo na tela).
  const CIDADE_PADRAO = {
    "ANAPOLIS":"ANP","ALEXANIA":"ALE","LUZIANIA":"LZI","CRISTALINA":"CRT","JARAGUA":"JAR","RIANAPOLIS":"RIA",
    "NIQUELANDIA":"NIQ","PIRENOPOLIS":"PIR","URUACU":"URU","RUBIATABA":"RUB","ITAPACI":"ITA","SANTA TEREZINHA DE GOIAS":"STZ"
  };
  const SEM = "SEM FILIAL DEFINIDA";
  let subAba = "controle"; // "controle" | "dashboard" | "cidades"
  const norm = s => (s||"").normalize("NFD").replace(/[\u0300-\u036f]/g,"").toUpperCase().trim();
  const num = s => Number(String(s||"0").replace(/\./g,"").replace(",","."))||0;
  const fmtKg = n => n.toLocaleString("pt-BR",{minimumFractionDigits:3,maximumFractionDigits:3});
  const brISO = b => { const m = (b||"").match(/(\d{2})\/(\d{2})\/(\d{4})/); return m ? `${m[3]}-${m[2]}-${m[1]}` : ""; };
  const regras = () => { try{ return JSON.parse(localStorage.getItem(K_CID)||"null") || {...CIDADE_PADRAO}; }catch(e){ return {...CIDADE_PADRAO}; } };
  const salvaRegras = r => localStorage.setItem(K_CID, JSON.stringify(r));
  const filialDe = (p, r) => p.filialManual || r[norm(p.cidade)] || "";

  /* ---------- parser ---------- */
  window.parseMapaPrevistas = function(text){
    text = text.replace(/\r\n/g,"\n").replace(/\n{2,}/g,"\n");
    const rota = ((text.match(/Rota:\s*([A-Z0-9]+(?:\s+[A-Z0-9-]+)*)\s+Entregas/i)||[])[1]||"").trim();
    const dataRota = brISO((text.match(/Data:\s*(\d{2}\/\d{2}\/\d{4})/)||[])[1]);
    const motorista = ((text.match(/Motorista:\s*\n?\s*([^\n]+)/i)||[])[1]||"").trim();
    const placa = ((text.match(/Placa:\s*([A-Z0-9]+)/i)||[])[1]||"").trim();
    const lixo = /^(Google Maps|Seq|Pacote|Rela[cç][aã]o|Nota Fiscal|Cliente|Peso|Volume|MAPA DE ENTREGA|TransFlow|https?:\/\/|\d{2}\/\d{2}\/\d{4},|entrega-VAL|Pacote\s*Rela|PesoVolume|\d{1,3}$|\d+\/\d+$)/i;
    const pacotes = [];
    text.split(/(?<!\d)(?=\d{4,}\s*\/\s*REL:\s*\d+)/g).slice(1).forEach((ch, i) => {
      const rel = ch.match(/(\d{4,})\s*\/\s*REL:\s*(\d+)/); if(!rel) return;
      const g = re => Number((ch.match(re)||[])[1]||0);
      const semData = /SEM DATA DE DESCARGA/i.test(ch);
      const limite = brISO((ch.match(/Data limite para entrega:\s*(\d{2}\/\d{2}\/\d{4})/i)||[])[1]);
      const tipoVenda = ((ch.match(/REL:\s*\d+\s*\n\s*([^\n]+)/)||[])[1]||"Venda normal").trim();
      // tudo depois do bloco de prazo/origem = NF, cliente, endereço, peso, m³
      const cut = ch.search(/Data limite para entrega:[^\n]*\n|PACOTE SEM DATA DE DESCARGA\s*\n|Origem:\s*TAMBASA\s*\n/i);
      const resto = ch.slice(cut).split("\n").slice(1).map(s=>s.trim()).filter(Boolean);
      const linhas = resto.filter(l => !lixo.test(l) || /^\d{5,}$/.test(l));
      const iNf = linhas.findIndex(l => /^\d{5,}$/.test(l)); if(iNf < 0) return;
      const iCod = linhas.findIndex((l,j) => j > iNf && /^\d+\s*-\s*[\d.\/-]+$/.test(l));
      const iKg = linhas.findIndex(l => /kg$/i.test(l));
      const topo = linhas.slice(iNf+1, iCod<0 ? iNf+3 : iCod);
      const seg = topo.length > 1 ? topo[topo.length-1] : "";
      const end = iCod < 0 ? [] : linhas.slice(iCod+1, iKg<0 ? undefined : iKg);
      const bc = (end.pop()||"");
      const k = bc.lastIndexOf(" - ");
      const cod = iCod < 0 ? ["",""] : linhas[iCod].split(/\s*-\s*(.+)/);
      pacotes.push({
        rota, dataRota, motorista, placa, seq: pacotes.length+1, pacote: rel[1], relnum: rel[2], tipoVenda,
        vDep: g(/DEPOSITO:\s*(\d+)/i), vSsi: g(/SCHAEFER:\s*(\d+)/i), vLoj: g(/LOJ[AÃ]O:\s*(\d+)/i), volumes: g(/Volumes:\s*(\d+)/i),
        nf: linhas[iNf], cliente: (topo.length>1 ? topo.slice(0,-1) : topo).join(" "), segmento: seg,
        codigo: cod[0], doc: cod[1]||"", endereco: end.join(" "),
        bairro: k<0 ? "" : bc.slice(0,k).trim(), cidade: (k<0 ? bc : bc.slice(k+3)).trim(),
        peso: iKg<0 ? 0 : num((linhas[iKg].match(/([\d.,]+)\s*kg/i)||[])[1]), m3: num((ch.match(/([\d.,]+)\s*m³/)||[])[1]),
        prazo: g(/Prazo da cidade:\s*(\d+)/i), limite, semData
      });
    });
    return {rota, dataRota, motorista, placa, pacotes};
  };

  /* ---------- dados agrupados ---------- */
  function filtrados(){
    const q = norm(document.getElementById("prevBusca").value);
    const rt = document.getElementById("prevRota").value, ff = document.getElementById("prevFilial").value;
    const r = regras();
    return load(K_PREV).filter(p => {
      const f = filialDe(p, r) || SEM;
      return (!rt || p.rota === rt) && (!ff || f === ff) && (!q || norm([p.cliente,p.cidade,p.nf,p.doc,p.relnum].join(" ")).includes(q));
    }).map(p => ({...p, filial: filialDe(p, r) || SEM}));
  }
  function agrupa(lista){
    const m = {};
    lista.forEach(p => (m[p.filial] = m[p.filial] || []).push(p));
    return Object.keys(m).sort((a,b) => a===SEM ? -1 : b===SEM ? 1 : a.localeCompare(b)).map(f => ({filial:f, itens:m[f]}));
  }
  const totais = it => ({vol: it.reduce((s,p)=>s+p.volumes,0), kg: it.reduce((s,p)=>s+p.peso,0), m3: it.reduce((s,p)=>s+p.m3,0)});
  const volTxt = p => [p.vDep && `Depósito: ${p.vDep}`, p.vSsi && `SSI Schaefer: ${p.vSsi}`, p.vLoj && `Lojão: ${p.vLoj}`].filter(Boolean).join(" · ");
  // NF repetida dentro do mesmo pacote/REL: o sistema guarda só 1 registro e marca com asterisco (*) quando houve duplicata
  const chavePac = p => `${String(p.pacote).trim()}|${String(p.relnum).trim()}|${String(p.nf).trim()}`; // pacote + REL + NF
  const nfTxt = p => p.dupQtd ? `${p.nf} *` : p.nf;
  const dupHint = p => `NF repetida dentro do pacote ${p.pacote} / REL ${p.relnum}: ${p.dupQtd} duplicata(s) ignorada(s)${(p.dupSeqs||[]).length ? " (Seq "+p.dupSeqs.join(", ")+")" : ""}. Foi mantido apenas 1 registro (as demais entregas do pacote foram lidas normalmente).`;
  const temDup = it => it.some(p => p.dupQtd);
  const NOTA_DUP = "* NF repetida dentro do pacote (duplicata ignorada)";
  const prazoTxt = p => p.semData ? "Sem data de descarga" : `${p.prazo ? p.prazo+" dia(s) · " : ""}até ${fmtDate(p.limite)}`;

  /* ---------- tela ---------- */
  window.previstasHTML = function(){
    return `
    <h2 class="section-title">Entregas Previstas — controle por filial</h2>
    <p class="section-desc">Importe o PDF do <strong>Mapa de Entrega</strong>. O sistema lê todos os dados de cada pacote (pacote/REL, tipo de venda, volumes, NF, cliente completo, peso e prazo), descobre a <strong>unidade atendida</strong> pela cidade e organiza tudo por filial — é isso que cada filial recebe como controle do dia seguinte. Se a filial não for a certa, troque no campo <em>Unidade atendida</em> do pacote ou ajuste a cidade na sub-aba <em>Cidades</em>.</p>
    <div class="panel"><div class="panel-header">Importar Mapa de Entrega (PDF)</div>
      <form class="add-form" id="formPrevPdf">
        <div class="field"><label>Arquivo(s) PDF</label><input type="file" id="prevPdfInput" accept="application/pdf" multiple></div>
        <div class="field" style="max-width:200px;"><button type="submit" class="btn btn-primary">Processar PDF</button></div>
        <div class="field full"><button type="button" class="link-btn" id="prevToggleTexto">ou colar o texto extraído do PDF manualmente</button></div>
      </form>
      <div id="prevTextoWrap" style="display:none; padding:0 18px 16px;">
        <textarea id="prevTexto" rows="5" style="width:100%; font-family:monospace; font-size:12px; padding:8px; border:1px solid var(--line); border-radius:6px;" placeholder="Cole aqui o texto do mapa de entrega..."></textarea>
        <div style="margin-top:8px;"><button type="button" class="btn btn-ghost btn-sm" id="prevProcessaTexto">Processar texto colado</button></div>
      </div>
      <div class="footer-note" id="prevStatus"></div></div>
    <div class="pg-subtabs" id="prevSubtabs">
      <button type="button" class="pg-subtab-btn ${subAba==='controle'?'active':''}" data-prev-sub="controle">Controle por filial</button>
      <button type="button" class="pg-subtab-btn ${subAba==='dashboard'?'active':''}" data-prev-sub="dashboard">Dashboard</button>
      <button type="button" class="pg-subtab-btn ${subAba==='cidades'?'active':''}" data-prev-sub="cidades">Cidades <span id="prevCidCount"></span></button>
    </div>
    <div class="pg-subview ${subAba==='cidades'?'active':''}" id="prevSub-cidades">
    <div class="panel"><div class="panel-header">Cidade → Filial que atende</div>
      <form class="add-form" id="formPrevCidade">
        <div class="field"><label>Cidade</label><input type="text" id="prevCidNome" placeholder="Ex: Anápolis" required></div>
        <div class="field" style="max-width:160px;"><label>Filial</label><select id="prevCidFilial">${FILIAIS.map(f=>`<option>${escHtml(f)}</option>`).join("")}</select></div>
        <div class="field" style="max-width:200px;"><button type="submit" class="btn btn-primary">Salvar cidade</button></div>
      </form>
      <div class="table-wrap" id="prevCidadesWrap"></div></div>
    </div>
    <div class="pg-subview ${subAba==='dashboard'?'active':''}" id="prevSub-dashboard"><div id="prevDash"></div></div>
    <div class="pg-subview ${subAba==='controle'?'active':''}" id="prevSub-controle">
    <div class="panel"><div class="panel-header">Controle por filial</div>
      <div class="toolbar">
        <label class="check-inline">Rota: <select class="small-select" id="prevRota"></select></label>
        <label class="check-inline">Filial: <select class="small-select" id="prevFilial"></select></label>
        <label class="check-inline">Buscar: <input type="text" class="small-input" id="prevBusca" placeholder="Cliente, cidade, NF..." style="width:180px;"></label>
        <span class="toolbar-actions">
          <button type="button" class="btn btn-ghost btn-sm" data-prev-exp="xlsx:">Exportar Excel</button>
          <button type="button" class="btn btn-ghost btn-sm" data-prev-exp="pdf:">Exportar PDF</button>
          <button type="button" class="link-btn danger" id="prevLimpar">Limpar importados</button></span>
      </div>
      <div id="prevLista"></div></div>
    </div>`;
  };

  function renderCidades(){
    const r = regras(), vistas = new Map();
    load(K_PREV).forEach(p => vistas.set(norm(p.cidade), p.cidade));
    Object.keys(r).forEach(c => { if(!vistas.has(c)) vistas.set(c, c); });
    const linhas = [...vistas.entries()].sort((a,b)=>a[1].localeCompare(b[1]));
    const semDef = linhas.filter(([n]) => !r[n]).length, cnt = document.getElementById("prevCidCount");
    if(cnt) cnt.innerHTML = semDef ? `<span class="badge" style="background:#c0392b;color:#fff;border-radius:10px;padding:1px 7px;font-size:11px;margin-left:4px;">${semDef}</span>` : "";
    document.getElementById("prevCidadesWrap").innerHTML = !linhas.length ? `<div class="empty">Nenhuma cidade ainda.</div>` : `
      <table><thead><tr><th>Cidade</th><th>Filial que atende</th><th>Pacotes</th><th></th></tr></thead><tbody>
      ${linhas.map(([n,nome]) => `<tr class="${r[n]?"":"row-warn"}"><td>${escHtml(nome)}</td>
        <td><select class="small-select" data-prev-cid="${escHtml(n)}"><option value="">— definir —</option>${FILIAIS.map(f=>`<option ${r[n]===f?"selected":""}>${escHtml(f)}</option>`).join("")}</select></td>
        <td>${load(K_PREV).filter(p=>norm(p.cidade)===n).length}</td>
        <td><button class="link-btn danger" data-prev-cid-del="${escHtml(n)}">Remover regra</button></td></tr>`).join("")}</tbody></table>`;
  }

  function renderFiltros(){
    const lista = load(K_PREV), r = regras();
    const rotaSel = document.getElementById("prevRota"), filSel = document.getElementById("prevFilial");
    const rv = rotaSel.value, fv = filSel.value;
    const rotas = [...new Set(lista.map(p=>p.rota))];
    rotaSel.innerHTML = `<option value="">Todas</option>` + rotas.map(x=>`<option ${x===rv?"selected":""}>${escHtml(x)}</option>`).join("");
    const fils = [...new Set(lista.map(p => filialDe(p, r) || SEM))].sort();
    filSel.innerHTML = `<option value="">Todas</option>` + fils.map(x=>`<option ${x===fv?"selected":""}>${escHtml(x)}</option>`).join("");
  }

  function renderLista(){
    const grupos = agrupa(filtrados()), box = document.getElementById("prevLista");
    if(!grupos.length){ box.innerHTML = `<div class="empty">Nenhum pacote importado.</div>`; return; }
    box.innerHTML = grupos.map(g => { const t = totais(g.itens); return `
      <div class="prev-filial-head ${g.filial===SEM?"sem":""}"><strong>${escHtml(g.filial)}</strong>
        <span>${g.itens.length} entrega(s) · ${t.vol} volumes · ${fmtKg(t.kg)} kg · ${t.m3.toLocaleString("pt-BR",{minimumFractionDigits:3})} m³</span>
        <span class="toolbar-actions"><button class="btn btn-ghost btn-sm" data-prev-exp="xlsx:${escHtml(g.filial)}">Excel</button>
        <button class="btn btn-ghost btn-sm" data-prev-exp="pdf:${escHtml(g.filial)}">PDF</button></span></div>
      <div class="table-wrap"><table><thead><tr><th>Seq</th><th>Pacote / Relação</th><th>Nota Fiscal</th><th>Cliente</th><th>Peso / Volume</th><th>Prazo</th><th>Unidade atendida</th></tr></thead><tbody>
      ${g.itens.map(p => `<tr class="${/troca/i.test(p.tipoVenda)?"row-alert":""}">
        <td>${p.seq}</td>
        <td><strong>${p.pacote} / REL: ${p.relnum}</strong><br>${escHtml(p.tipoVenda)}<br><small>${volTxt(p)}<br>Volumes: ${p.volumes}</small></td>
        <td>${escHtml(p.nf)}${p.dupQtd ? ` <span class="nf-dup" title="${escHtml(dupHint(p))}">*</span>` : ""}</td>
        <td><strong>${escHtml(p.cliente)}</strong><br>${escHtml(p.segmento)}<br><small>${escHtml(p.codigo)} - ${escHtml(p.doc)}<br>${escHtml(p.endereco)}<br>${escHtml(p.bairro)} - ${escHtml(p.cidade)}</small></td>
        <td>${fmtKg(p.peso)} kg<br>${p.m3.toLocaleString("pt-BR",{minimumFractionDigits:3})} m³</td>
        <td>${escHtml(prazoTxt(p))}</td>
        <td><select class="small-select" data-prev-pk="${p.id}"><option value="">Automático${p.filialManual?"":" ("+escHtml(p.filial)+")"}</option>
          ${FILIAIS.map(f=>`<option ${p.filialManual===f?"selected":""}>${escHtml(f)}</option>`).join("")}</select></td></tr>`).join("")}
      </tbody></table></div>
      ${temDup(g.itens) ? `<div class="footer-note nf-dup-note"><span class="nf-dup">*</span> NF repetida dentro do pacote — a duplicata foi ignorada e só 1 registro foi mantido; as outras entregas do pacote foram lidas normalmente. Passe o mouse no asterisco para ver os detalhes.</div>` : ""}`; }).join("");
  }
  
  /* ---------- dashboard simples: volumes e entregas por unidade ---------- */
  function renderDash(){
    const box = document.getElementById("prevDash"); if(!box) return;
    const r = regras();
    const lista = load(K_PREV).map(p => ({...p, filial: filialDe(p, r) || SEM}));
    if(!lista.length){ box.innerHTML = `<div class="panel"><div class="empty">Importe o Mapa de Entrega para ver o dashboard.</div></div>`; return; }
    const gr = agrupa(lista).map(g => ({filial:g.filial, ent:g.itens.length, vol:totais(g.itens).vol}));
    const totVol = gr.reduce((s,g)=>s+g.vol,0), totEnt = gr.reduce((s,g)=>s+g.ent,0);
    const n = v => v.toLocaleString("pt-BR");
    const trocas = lista.filter(p => /troca/i.test(p.tipoVenda)).sort((a,b) => a.filial.localeCompare(b.filial) || String(a.cliente).localeCompare(String(b.cliente)));
    const grafico = (titulo, campo, cor) => {
      const ord = [...gr].sort((a,b) => b[campo]-a[campo] || a.filial.localeCompare(b.filial)), max = Math.max(...ord.map(g=>g[campo]), 1);
      return `<div class="panel"><div class="panel-header">${titulo}</div><div class="pdash-chart">
        ${ord.map(g => `<div class="pdash-row"><span class="pdash-lab" title="${escHtml(g.filial)}">${escHtml(g.filial)}</span>
          <span class="pdash-track"><span class="pdash-bar" style="width:${Math.max(g[campo]/max*100, 1.5).toFixed(1)}%;background:${g.filial===SEM?"#c0392b":cor}"></span></span>
          <strong class="pdash-val">${n(g[campo])}</strong></div>`).join("")}</div></div>`;
    };
    box.innerHTML = `
      <div class="kpi-grid">
        <div class="kpi-card"><div class="label">Volumes a entregar (total)</div><div class="value">${n(totVol)}</div></div>
        <div class="kpi-card"><div class="label">Entregas (total)</div><div class="value">${n(totEnt)}</div></div>
        <div class="kpi-card"><div class="label">Unidades atendidas</div><div class="value">${n(gr.filter(g=>g.filial!==SEM).length)}</div></div>
        <div class="kpi-card ${trocas.length?"alert":"ok"}"><div class="label">Trocas a fazer</div><div class="value">${n(trocas.length)}</div><div class="hint">${trocas.length ? "NF(s) de SAC - Troca / Falta nesta entrega" : "Nenhuma troca nesta entrega"}</div></div>
      </div>
      <div class="pdash-grid">${grafico("Volumes por unidade","vol","#2c4bb0")}${grafico("Entregas por unidade","ent","#16a085")}</div>
      <div class="panel"><div class="panel-header">Resumo por unidade</div><div class="table-wrap"><table><thead><tr><th>Unidade</th><th style="text-align:right">Entregas</th><th style="text-align:right">Volumes</th></tr></thead><tbody>
        ${gr.map(g => `<tr class="${g.filial===SEM?"row-warn":""}"><td><strong>${escHtml(g.filial)}</strong></td><td style="text-align:right">${n(g.ent)}</td><td style="text-align:right">${n(g.vol)}</td></tr>`).join("")}
        <tr><td><strong>TOTAL</strong></td><td style="text-align:right"><strong>${n(totEnt)}</strong></td><td style="text-align:right"><strong>${n(totVol)}</strong></td></tr></tbody></table></div></div>
      <div class="panel"><div class="panel-header">Trocas a fazer — NF e cliente <span class="badge" style="background:${trocas.length?"#c0392b":"#16a085"};color:#fff;border-radius:10px;padding:1px 8px;font-size:11px;margin-left:6px;">${trocas.length}</span></div>
        ${!trocas.length ? `<div class="empty">Nenhuma troca nas entregas previstas importadas.</div>` : `<div class="table-wrap"><table><thead><tr><th>Nota Fiscal</th><th>Cliente (quem é a troca)</th><th>Cidade</th><th>Unidade</th><th>Pacote / Relação</th><th>Tipo</th><th>Prazo</th></tr></thead><tbody>
        ${trocas.map(p => `<tr class="row-alert"><td><strong>${escHtml(p.nf)}</strong>${p.dupQtd ? ` <span class="nf-dup" title="${escHtml(dupHint(p))}">*</span>` : ""}</td>
          <td><strong>${escHtml(p.cliente)}</strong><br>${escHtml(p.segmento)}<br><small>${escHtml(p.codigo)} - ${escHtml(p.doc)}<br>${escHtml(p.endereco)}</small></td>
          <td>${escHtml(p.bairro)}${p.bairro && p.cidade ? " - " : ""}${escHtml(p.cidade)}</td>
          <td><strong>${escHtml(p.filial)}</strong></td>
          <td>${escHtml(p.pacote)} / REL: ${escHtml(p.relnum)}<br><small>Rota ${escHtml(p.rota)}</small></td>
          <td>${escHtml(p.tipoVenda)}</td>
          <td>${escHtml(prazoTxt(p))}</td></tr>`).join("")}
        </tbody></table></div>`}</div>`;
  }
  const renderTudo = () => { renderCidades(); renderFiltros(); renderLista(); renderDash(); };

  /* ---------- exportação ---------- */
  const cab = ["Seq","Pacote / Relação","Tipo de venda","Volumes","Nota Fiscal","Cliente","Segmento","Código - CNPJ/CPF","Endereço","Bairro","Cidade","Peso (kg)","m³","Prazo","Data limite","Unidade atendida"];
  const linha = p => [p.seq, `${p.pacote} / REL: ${p.relnum}`, p.tipoVenda, `${volTxt(p)}${volTxt(p)?" · ":""}Total: ${p.volumes}`, nfTxt(p), p.cliente, p.segmento, `${p.codigo} - ${p.doc}`, p.endereco, p.bairro, p.cidade, p.peso, p.m3, p.semData?"Sem data de descarga":(p.prazo?p.prazo+" dias":""), p.semData?"":fmtDate(p.limite), p.filial];

  async function exportaExcel(grupos){
    if(typeof ExcelJS === "undefined"){ alert("Biblioteca de Excel (ExcelJS) não carregou. Verifique a internet e recarregue."); return; }
    const wb = new ExcelJS.Workbook(); wb.creator = "Painel Tambasa";
    const fino = {style:"thin", color:{argb:"FFBFBFBF"}}, borda = {top:fino,bottom:fino,left:fino,right:fino};
    const usados = new Set();
    grupos.forEach(g => {
      let nome = g.filial.slice(0,31); while(usados.has(nome)) nome += "_"; usados.add(nome);
      const ws = wb.addWorksheet(nome, {views:[{state:"frozen", ySplit:3, showGridLines:false}]});
      ws.mergeCells(1,1,1,cab.length);
      const t = ws.getCell("A1"); t.value = `ENTREGAS PREVISTAS — ${g.filial}`; t.font = {name:"Arial",size:14,bold:true,color:{argb:"FFFFFFFF"}};
      t.fill = {type:"pattern",pattern:"solid",fgColor:{argb:"FF0F172A"}}; ws.getRow(1).height = 24;
      const tt = totais(g.itens);
      ws.mergeCells(2,1,2,cab.length);
      ws.getCell("A2").value = `${g.itens.length} entrega(s) · ${tt.vol} volumes · ${fmtKg(tt.kg)} kg · ${tt.m3.toFixed(3)} m³ · Rota(s): ${[...new Set(g.itens.map(p=>p.rota))].join(", ")}${temDup(g.itens) ? " · "+NOTA_DUP : ""}`;
      ws.getCell("A2").font = {name:"Arial",size:10,italic:true};
      ws.addRow(cab).eachCell(c => { c.font = {name:"Arial",size:10,bold:true,color:{argb:"FFFFFFFF"}}; c.fill = {type:"pattern",pattern:"solid",fgColor:{argb:"FF0F172A"}}; c.alignment = {vertical:"middle",horizontal:"center",wrapText:true}; c.border = borda; });
      g.itens.forEach((p,i) => ws.addRow(linha(p)).eachCell({includeEmpty:true}, (c,n) => {
        c.font = {name:"Arial",size:9}; c.border = borda; c.alignment = {vertical:"top",wrapText:true, horizontal: n===12||n===13?"right":"left"};
        if(n===12) c.numFmt = "#,##0.000"; if(n===13) c.numFmt = "0.000";
        if(i%2===0) c.fill = {type:"pattern",pattern:"solid",fgColor:{argb:"FFF1F5F9"}};
      }));
      [5,22,16,30,11,38,26,26,34,22,20,11,8,18,12,12].forEach((w,i) => ws.getColumn(i+1).width = w);
      ws.pageSetup = {orientation:"landscape", fitToPage:true, fitToWidth:1, fitToHeight:0};
    });
    const buf = await wb.xlsx.writeBuffer();
    const a = document.createElement("a"); a.href = URL.createObjectURL(new Blob([buf],{type:"application/vnd.openxmlformats-officedocument.spreadsheetml.sheet"}));
    a.download = `Entregas_Previstas_${grupos.length===1?grupos[0].filial+"_":""}${window.dataParaArquivo?dataParaArquivo():""}.xlsx`;
    document.body.appendChild(a); a.click(); a.remove(); setTimeout(()=>URL.revokeObjectURL(a.href),2000);
  }

  /* logos do cabeçalho do PDF (embutidos: funcionam offline e na janela de impressão) */
  const LOGO_TAMBASA = "data:image/png;base64,";
  const LOGO_DOVALLE = "data:image/png;base64,";

  /* PDF em PAISAGEM de verdade (jsPDF): a pagina ja nasce A4 deitada, entao abre e salva sempre em modo paisagem.
     Se as bibliotecas nao carregarem (offline), cai no modo antigo de impressao (tambem em paisagem). */
  function exportaPdf(grupos){
    const J = window.jspdf && window.jspdf.jsPDF;
    if(!J){ return exportaPdfImpressao(grupos); }
    try{
      const doc = new J({orientation:"landscape", unit:"mm", format:"a4"});
      if(typeof doc.autoTable !== "function"){ return exportaPdfImpressao(grupos); }
      const L = s => String(s == null ? "" : s).replace(/[\u2013\u2014]/g,"-").replace(/[^\u0000-\u00FF]/g,"");
      const PW = doc.internal.pageSize.getWidth(), M = 10;
      let logoDv = null, logoTb = null;
      try{
        const a = doc.getImageProperties(LOGO_DOVALLE), b = doc.getImageProperties(LOGO_TAMBASA);
        logoDv = {h:12, w:12*a.width/a.height}; logoTb = {h:9, w:9*b.width/b.height};
      }catch(_){}
      const logosW = logoDv && logoTb ? logoDv.w + logoTb.w + 8 : 0;
      grupos.forEach((g, gi) => {
        if(gi > 0) doc.addPage("a4","landscape");
        const t = totais(g.itens);
        const titulo = L("ENTREGAS PREVISTAS - " + g.filial);
        const sub = L(g.itens.length + " entrega(s) | " + t.vol + " volumes | " + fmtKg(t.kg) + " kg | " + t.m3.toFixed(3) + " m3 | Rota(s): " + [...new Set(g.itens.map(p => p.rota))].join(", ") + (temDup(g.itens) ? " | " + NOTA_DUP : ""));
        const cabecalho = () => {
          const bw = PW - 2*M - (logosW ? logosW + 4 : 0);
          doc.setFillColor(15,23,42); doc.rect(M, M, bw, 10, "F");
          doc.setTextColor(255,255,255); doc.setFont("helvetica","bold"); doc.setFontSize(13); doc.text(titulo, M+3, M+6.8);
          doc.setTextColor(68,68,68); doc.setFont("helvetica","normal"); doc.setFontSize(9); doc.text(sub, M, M+16, {maxWidth: bw});
          if(logoDv && logoTb){
            let x = PW - M - logosW;
            try{ doc.addImage(LOGO_DOVALLE,"PNG",x,M-1,logoDv.w,logoDv.h); doc.addImage(LOGO_TAMBASA,"PNG",x+logoDv.w+8,M+1,logoTb.w,logoTb.h); }catch(_){}
          }
        };
        const linhas = g.itens.map(p => [
          L(p.seq),
          [L(p.pacote + " / REL: " + p.relnum), L(p.tipoVenda), L(volTxt(p)), L("Volumes: " + p.volumes)].filter(Boolean).join("\n"),
          L(nfTxt(p)),
          [L(p.cliente), L(p.segmento), L(p.codigo + " - " + p.doc), L(p.endereco), L(p.bairro + " - " + p.cidade)].filter(x => x && x.trim()).join("\n"),
          L(fmtKg(p.peso) + " kg\n" + p.m3.toFixed(3) + " m3"),
          L(prazoTxt(p)),
          L(p.filial)
        ]);
        doc.autoTable({
          head:[["Seq","Pacote / Relacao","Nota Fiscal","Cliente","Peso / Volume","Prazo","Unidade"]],
          body: linhas,
          startY: M + 21,
          margin:{top: M + 21, left: M, right: M, bottom: 12},
          theme:"grid",
          rowPageBreak:"avoid",
          styles:{font:"helvetica", fontSize:8, cellPadding:1.6, lineColor:[187,187,187], lineWidth:0.2, textColor:[28,35,51], valign:"top"},
          headStyles:{fillColor:[15,23,42], textColor:[255,255,255], halign:"center"},
          alternateRowStyles:{fillColor:[241,245,249]},
          columnStyles:{0:{cellWidth:10,halign:"center"},1:{cellWidth:48,halign:"center"},2:{cellWidth:24,halign:"center"},3:{cellWidth:"auto"},4:{cellWidth:28,halign:"right"},5:{cellWidth:32,halign:"center"},6:{cellWidth:22,halign:"center",fontStyle:"bold"}},
          didDrawPage: cabecalho
        });
      });
      const n = doc.internal.getNumberOfPages();
      for(let i = 1; i <= n; i++){
        doc.setPage(i); doc.setFont("helvetica","normal"); doc.setFontSize(8); doc.setTextColor(120,120,120);
        doc.text("Pagina " + i + " de " + n, PW - M, doc.internal.pageSize.getHeight() - 5, {align:"right"});
      }
      const d = new Date(), pad = n => String(n).padStart(2,"0");
      const hoje = pad(d.getDate()) + "-" + pad(d.getMonth()+1) + "-" + d.getFullYear();
      const unidade = grupos.length === 1 ? String(grupos[0].filial).replace(/[\\/:*?"<>|]+/g,"-").trim() : "Geral";
      const nome = "Tambasa " + hoje + " _ " + unidade + ".pdf";
      doc.save(nome);
    }catch(err){
      console.error(err); exportaPdfImpressao(grupos);
    }
  }

  function exportaPdfImpressao(grupos){
    const w = window.open("", "_blank");
    if(!w){ alert("O navegador bloqueou a janela do PDF. Permita pop-ups para este site e tente de novo."); return; }
    const e = escHtml;
    w.document.write(`<!DOCTYPE html><html><head><meta charset="utf-8"><title>Entregas Previstas</title><style>
      @page{size:A4 landscape;margin:10mm} *{-webkit-print-color-adjust:exact;print-color-adjust:exact} body{font-family:Arial,sans-serif;font-size:9px;color:#1c2333}
      .pg{page-break-after:always} .pg:last-child{page-break-after:auto}
      .cab{display:flex;justify-content:space-between;align-items:center;gap:12px;margin:0 0 8px}
      .cab-txt{flex:1;min-width:0} .cab-logos{display:flex;align-items:center;gap:14px;flex:none}
      .cab-logos img{display:block;object-fit:contain}
      .lg-dv{height:40px} .lg-tb{height:30px}
      h1{font-size:15px;background:#0f172a;color:#fff;padding:8px 10px;margin:0;-webkit-print-color-adjust:exact;print-color-adjust:exact} .sub{font-size:10px;margin:5px 0 0;color:#444}
      table{width:100%;border-collapse:collapse} th{background:#0f172a;color:#fff;padding:4px;border:1px solid #999}
      td{border:1px solid #bbb;padding:4px;vertical-align:top} tr{page-break-inside:avoid} tbody tr:nth-child(even){background:#f1f5f9}
      .c{text-align:center} .r{text-align:right;white-space:nowrap}</style></head><body>
      ${grupos.map(g => { const t = totais(g.itens); return `<div class="pg"><div class="cab"><div class="cab-txt"><h1>ENTREGAS PREVISTAS — ${e(g.filial)}</h1>
        <div class="sub">${g.itens.length} entrega(s) · ${t.vol} volumes · ${fmtKg(t.kg)} kg · ${t.m3.toFixed(3)} m³ · Rota(s): ${e([...new Set(g.itens.map(p=>p.rota))].join(", "))}${temDup(g.itens) ? " · "+e(NOTA_DUP) : ""}</div></div>
        <div class="cab-logos"><img class="lg-dv" src="${LOGO_DOVALLE}" alt="Do Valle"><img class="lg-tb" src="${LOGO_TAMBASA}" alt="Tambasa"></div></div>
        <table><thead><tr><th>Seq</th><th>Pacote / Relação</th><th>Nota Fiscal</th><th>Cliente</th><th>Peso / Volume</th><th>Prazo</th><th>Unidade</th></tr></thead><tbody>
        ${g.itens.map(p => `<tr><td class="c">${p.seq}</td>
          <td class="c"><b>${p.pacote} / REL: ${p.relnum}</b><br>${e(p.tipoVenda)}<br>${e(volTxt(p))}<br>Volumes: ${p.volumes}</td>
          <td class="c">${e(nfTxt(p))}</td>
          <td><b>${e(p.cliente)}</b><br><b>${e(p.segmento)}</b><br>${e(p.codigo)} - ${e(p.doc)}<br>${e(p.endereco)}<br>${e(p.bairro)} - ${e(p.cidade)}</td>
          <td class="r">${fmtKg(p.peso)} kg<br>${p.m3.toFixed(3)} m³</td><td class="c">${e(prazoTxt(p))}</td><td class="c"><b>${e(p.filial)}</b></td></tr>`).join("")}
        </tbody></table></div>`; }).join("")}
      <script>window.onload=function(){setTimeout(function(){window.print()},300)}<\/script></body></html>`);
    w.document.close();
  }

  /* ---------- eventos ---------- */
  /* Dentro de cada pacote (pacote + REL) a mesma NF não pode aparecer duas vezes. O sistema lê TODAS as entregas do pacote;
     se uma NF vier repetida no mesmo pacote/REL, a duplicata é ignorada e o registro mantido recebe o asterisco (*).
     A mesma NF em outro pacote/REL é outra entrega e é mantida. Reimportar o mesmo PDF não gera asterisco. */
  function importa(parsed, st){
    const ex = load(K_PREV), lote = uid(), porChave = new Map(ex.map(p => [chavePac(p), p]));
    let novos = 0, reimp = 0; const dups = [];
    parsed.pacotes.forEach(p => {
      const k = chavePac(p), o = porChave.get(k);
      if(o){
        if(o.imp !== lote && o.rota === p.rota){ reimp++; return; } // mesmo mapa importado de novo
        o.dupQtd = (o.dupQtd || 0) + 1; (o.dupSeqs = o.dupSeqs || []).push(p.seq);
        dups.push(`pacote ${p.pacote} / REL ${p.relnum} · NF ${String(p.nf).trim()} (Seq ${p.seq})`); return;
      }
      const novo = {id:uid(), imp:lote, ...p}; ex.push(novo); porChave.set(k, novo); novos++;
    });
    save(K_PREV, ex);
    st.push(`Rota ${parsed.rota||"-"} (${fmtDate(parsed.dataRota)}): ${parsed.pacotes.length} entrega(s) lida(s), ${novos} nova(s)${reimp ? `, ${reimp} já importada(s) antes` : ""}.`);
    if(dups.length) st.push(`⚠ ${dups.length} NF repetida(s) dentro do pacote, ignorada(s) e marcada(s) com *: ${dups.join("; ")}.`);
  }

  // Limpa duplicatas de importações antigas (mesmo pacote + REL + NF): mantém o 1º registro e marca com *
  function limpaDuplicadasNF(){
    const ex = load(K_PREV), vistos = new Map(); let removidas = 0;
    ex.forEach(p => {
      const k = chavePac(p), o = vistos.get(k);
      if(!o){ vistos.set(k, p); return; }
      o.dupQtd = (o.dupQtd || 0) + 1; (o.dupSeqs = o.dupSeqs || []).push(p.seq); p._rm = true; removidas++;
    });
    if(removidas) save(K_PREV, ex.filter(p => !p._rm));
    return removidas;
  }

  window.attachPrevistasEvents = function(){
    const st = document.getElementById("prevStatus"), root = document.getElementById("sec-previstas");
    document.getElementById("prevToggleTexto").onclick = () => { const w = document.getElementById("prevTextoWrap"); w.style.display = w.style.display==="none"?"block":"none"; };
    document.getElementById("formPrevPdf").addEventListener("submit", async e => {
      e.preventDefault();
      const files = [...document.getElementById("prevPdfInput").files];
      if(!files.length){ st.textContent = "Selecione o PDF."; return; }
      st.textContent = "Lendo o PDF..."; const msgs = [];
      try{
        for(const f of files) importa(parseMapaPrevistas(await extractPdfText(f)), msgs);
        st.innerHTML = msgs.map(escHtml).join("<br>"); document.getElementById("prevPdfInput").value = ""; renderTudo();
      }catch(err){ st.innerHTML = `Não foi possível ler o PDF. <small>${escHtml(err.message||err)}</small><br>Tente colar o texto manualmente.`; }
    });
    document.getElementById("prevProcessaTexto").onclick = () => {
      const t = document.getElementById("prevTexto").value; if(!t.trim()){ st.textContent = "Cole o texto antes."; return; }
      const m = []; importa(parseMapaPrevistas(t), m); st.textContent = m.join(" "); document.getElementById("prevTexto").value = ""; renderTudo();
    };
    document.getElementById("formPrevCidade").addEventListener("submit", e => {
      e.preventDefault(); const r = regras(), n = norm(document.getElementById("prevCidNome").value);
      if(!n) return; r[n] = document.getElementById("prevCidFilial").value; salvaRegras(r); e.target.reset(); renderTudo();
    });
    document.getElementById("prevLimpar").onclick = () => { if(confirm("Remover todas as entregas previstas importadas? (as regras de cidade são mantidas)")){ save(K_PREV, []); renderTudo(); } };
    ["prevRota","prevFilial"].forEach(id => document.getElementById(id).addEventListener("change", renderLista));
    document.getElementById("prevBusca").addEventListener("input", renderLista);
    root.addEventListener("change", e => {
      const c = e.target.dataset;
      if(c.prevCid !== undefined){ const r = regras(); if(e.target.value) r[c.prevCid] = e.target.value; else delete r[c.prevCid]; salvaRegras(r); renderTudo(); }
      else if(c.prevPk){ const l = load(K_PREV), p = l.find(x => x.id === c.prevPk); if(p){ if(e.target.value) p.filialManual = e.target.value; else delete p.filialManual; save(K_PREV, l); renderTudo(); } }
    });
    root.addEventListener("click", e => {
      const b = e.target.closest("button"); if(!b) return;
      if(b.dataset.prevSub){
        subAba = b.dataset.prevSub;
        root.querySelectorAll("#prevSubtabs .pg-subtab-btn").forEach(x => x.classList.toggle("active", x.dataset.prevSub === subAba));
        ["controle","dashboard","cidades"].forEach(id => { const v = document.getElementById("prevSub-"+id); if(v) v.classList.toggle("active", id === subAba); });
        return;
      }
      if(b.dataset.prevCidDel !== undefined){ const r = regras(); delete r[b.dataset.prevCidDel]; salvaRegras(r); renderTudo(); }
      else if(b.dataset.prevExp){
        const [tipo, fil] = b.dataset.prevExp.split(":");
        let g = agrupa(filtrados()); if(fil) g = g.filter(x => x.filial === fil);
        if(!g.length){ alert("Não há entregas para exportar."); return; }
        tipo === "xlsx" ? exportaExcel(g) : exportaPdf(g);
      }
    });
    const lim = limpaDuplicadasNF();
    if(lim) st.textContent = `${lim} NF duplicada(s) dentro de pacote, de importações anteriores, foi(ram) unificada(s) e marcada(s) com *.`;
    renderTudo();
  };
})();
